here = fileparts(fileparts(mfilename('fullpath'))); addpath(here); addpath([here '/em']);
E_="try, ";
R('zoo times', 'z=zoo(interval(1,2),{''interval''}); try, r=z.*z; out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('zoo rdivide', 'z=zoo(interval(1,2),{''interval''}); try, r=z./z; out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('zoo mtimes', 'z=zoo(interval(1,2),{''interval''}); try, r=z*z; out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('tensorMult', 'Z=zonotope([0;0],eye(2)); M=cell(2,1); M{1}=eye(2); M{2}=eye(2); try, r=tensorMultiplication(Z,M,struct()); out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('tensorMult2', 'Z=zonotope([0;0],eye(2)); M=cell(2,1); M{1}=eye(2); M{2}=eye(2); try, r=tensorMultiplication(Z,M,[]); out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('nn relu cZ', 'nn=neuralNetwork({nnReLULayer()}); cZ=conZonotope([0;0],[1;-1]); r=nn.evaluate(cZ); V=vertices(r); out=sprintf("result vertices %s (true after ReLU: (0,1) and (1,0))",mat2str(sortrows(V'' ,1)'',3));');
R('nn elemAffine', 'nn=neuralNetwork({nnElementwiseAffineLayer([2;3],[0;1])}); try, r=nn.evaluate(conZonotope([0;0],eye(2))); out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('nn exp', 'nn=neuralNetwork({nnExpLayer()}); try, r=nn.evaluate(zonotope(0,1)); out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('nn exp2', 'nn=neuralNetwork({nnExpLayer()}); try, r=nn.evaluate(zonotope(0,1),struct("nn",struct("poly_method","regression"))); out=class(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('nn square interval', 'nn=neuralNetwork({nnSquareLayer()}); r=nn.evaluate(interval(-1,2)); out=sprintf("[%g,%g]",r.inf,r.sup);');
R('nn sin interval', 'L=nnActLayerFromHandle(@(x) sin(x)); nn=neuralNetwork({L}); r=nn.evaluate(interval(0,3)); out=sprintf("[%g,%g]",r.inf,r.sup);');
R('nn linear d', 'L=nnLinearLayer(1,0); L.d=interval(-1,1); nn=neuralNetwork({L}); r1=nn.evaluate(interval(0,0)); r2=nn.evaluate(conZonotope(0,0)); out=sprintf("interval [%g,%g]; conZonotope %s",r1.inf,r1.sup,class(r2)); try, I=interval(r2); out=out+sprintf(" -> [%g,%g]",I.inf,I.sup); catch, end; out=char(out);');
R('nn root df', 'L=nnRootLayer(); out=sprintf("df(4)=%g (sqrt derivative 0.25)",L.df(4));');
R('nn minMaxDiffOrder', 'L=nnActLayerFromHandle(@(x) exp(x), "myexp", 2, "myexp"); m=(exp(1)-exp(-1))/2; b=(exp(1)+exp(-1))/2; [dl,du]=nnHelper.minMaxDiffOrder(L,[m b],-1,1); xx=linspace(-1,1,20001); y=exp(xx)-(m*xx+b); out=sprintf("CORA [%g,%g]; true range [%g,%g]",dl,du,min(y),max(y));');
R('spec check custom', 'Sok=zonotope(0,1); Sbad=zonotope(5,1); spec=specification(@(S) contains(interval(-3,3),interval(S)),"custom"); try, r=check(spec,{Sok,Sbad}); out=num2str(r); catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('spec robustness', 'P=polytope([eye(3);-eye(3)],[1;1;1;0;0;0]); spec=specification(P,"safeSet"); r1=robustness(spec,[2;2;0.5]); r2=robustness(spec,[2;2;2]); out=sprintf("robustness at (2,2,.5) = %g, at (2,2,2) = %g",r1,r2);');
R('stl until true', 'x=stl("x",2); eq=until(x(1)<5, stl(true), interval(0,1)); r=eliminateTrueFalse(eq); out=char(string(r));');
R('stl nnf', 'x=stl("x",1); eq=~(x(1)<5); r=negationNormalForm(eq); out=char(string(r));');
R('stl polytope2stl', 'x=stl("x",1); P=polytope(1,5,1,2); r=polytope2stl(x,P); out=char(string(r));');
R('stlInterval minkDiff', 'a=stlInterval(0,Inf); r=minkDiff(a,a); out=char(string(r));');
R('intervalMatrix expm', 'M=intervalMatrix(-1,0); r=expmDifferentAlgorithms(M,2,0); out=sprintf("%s ; exp(-1)=%g 13/18=%g",mat2str(r.int.inf),exp(-1),13/18);');
R('intervalMatrix expm2', 'M=intervalMatrix(-1,0); r=expmTaylorHornerScaling(M,1,2); out=sprintf("[%g,%g]  exp(-1)=%g",r.int.inf,r.int.sup,exp(-1));');
R('intervalMatrix randPoint', 'M=intervalMatrix(0,1); x=randPoint(M,1000); y=randPoint(M,1000,"extreme"); out=sprintf("standard range [%g,%g]; extreme values %s",min(x(:)),max(x(:)),mat2str(unique(round(y(:),6))''));');
R('matPolytope plus', 'A=[0 1;1 0]; B=[0 1;0 1]; r=matPolytope(cat(3,A,B))+matPolytope(zeros(2,2)); out=sprintf("number of vertices %d",size(r.V,3));');
R('matPolytope expmIndMixed', 'V=cat(3,[0 1;1 0],[0 1;0 1]); try, r=expmIndMixed(matPolytope(V),1,3); out="ran"; catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('matZonotope reduce', 'mZ=matZonotope(zeros(2,2),ones(2,2,3)); try, r=reduce(mZ,"girard",2); out="ran"; catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('matZonotope replaceId', 'mZ=matZonotope(zeros(2,2),ones(2,2,3)); try, r=replaceId(mZ,[1;2]); out="ran"; catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
R('matZonotope vertices', 'mZ=matZonotope(zeros(1,4),ones(1,4)); v=vertices(mZ); out=sprintf("class %s size %s",class(v),mat2str(size(v{1})));');
R('matZonotope vertices2', 'mZ=matZonotope(zeros(2,3),ones(2,3)); try, v=vertices(mZ); out="ran"; catch ME, out=char(ME.message + " @ " + ME.stack(1).name + ":" + ME.stack(1).line); end');
